package org.jetbrains.plugins.scala.compiler.highlighting.core

import com.intellij.openapi.components.Service
import com.intellij.openapi.project.Project

/**
 * Project state generated by compiler.
 * Using for storing highlightings.
 */
private[highlighting] object CompilerGeneratedStateManager {

  def get(project: Project): CompilerGeneratedState =
    mutableState(project).state

  def update(project: Project, newState: CompilerGeneratedState): CompilerGeneratedState = {
    mutableState(project).state = newState
    newState
  }

  private def mutableState(project: Project): MutableState =
    project.getService(classOf[MutableState])

  @Service
  private final class MutableState {

    /**
     * Volatile for safe publication: this is written on the thread that emits the compiler events and read
     * from others.
     *
     * Read-modify-write across [[get]] and [[update]] is deliberately not atomic. That is sound only because
     * compilations, and so the event streams that write here, are serialised by the compiler lock — a second
     * concurrent writer would silently lose updates.
     */
    @volatile var state: CompilerGeneratedState = CompilerGeneratedState(Map.empty, Set.empty)
  }
}
